                <path d={c.d} fill="none" stroke={`url(#line-${agent.id})`} strokeWidth={2.6 + 1.4 * busy} strokeLinecap="round" opacity={0.5 + 0.45 * busy} strokeDasharray={dash} strokeDashoffset={offset} />
                {/* data flowing outwards once connected */}
