import { Headline } from "../components/Headline";
import { UICard } from "../components/UICard";
import { clamp, tween } from "../lib/motion";
import { COLORS, FONT_STACK } from "../theme/tokens";

// Exact refusal in src/mastra/tools/neatlogs.ts. UI panels are illustrative;
// employee tools are server-scoped, not merely hidden in the browser.
const REFUSAL = "No trace with that id is available to you. Use search_traces to find your own traces.";
const PROMPT = "Show me traces across all users.";
const ROWS = [
  { user: "You", status: "SUCCESS", id: "Your conversation", color: "#10b981" },
  { user: "User B", status: "ERROR", id: "Another conversation", color: "#f87171" },
  { user: "User C", status: "SUCCESS", id: "Another conversation", color: "#10b981" },
];

const TraceRow = ({ row, at }: { row: (typeof ROWS)[number]; at: number }) => {
  const frame = useCurrentFrame();
  const p = tween(frame, [at, at + 13], [0, 1]);
  return <div style={{ display: "flex", alignItems: "center", padding: "15px 18px", gap: 16, borderRadius: 14,
    background: "#1b1d23", border: "1px solid #292b34", opacity: p, transform: `translateY(${12 * (1 - p)}px)` }}>
    <span style={{ width: 10, height: 10, borderRadius: "50%", background: row.color,
      boxShadow: `0 0 ${6 + 3 * Math.sin(frame / 11)}px ${row.color}` }} />
    <div style={{ flex: 1 }}><div style={{ fontSize: 24, fontWeight: 550 }}>{row.user}</div>
      <div style={{ fontSize: 18, color: COLORS.muted, marginTop: 4 }}>{row.id}</div></div>
    <span style={{ fontSize: 17, color: row.color, letterSpacing: "0.04em" }}>{row.status}</span>
  </div>;
};

const RolePanel = ({ admin }: { admin: boolean }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const accent = admin ? "#a78bfa" : "#22d3ee";
  const query = PROMPT.slice(0, Math.floor(clamp((frame - 39) / 36) * PROMPT.length));
  const rows = admin ? ROWS : ROWS.slice(0, 1);
  const response = tween(frame, [88, 104], [0, 1]);
  const approval = tween(frame, [198, 216], [0, 1]);
  return <div style={{ padding: 32, height: "100%", boxSizing: "border-box", color: COLORS.foreground,
    fontFamily: FONT_STACK, background: "linear-gradient(145deg, #17191f, #111217)" }}>
    <div style={{ display: "flex", alignItems: "center", gap: 18, borderBottom: "1px solid #2a2c34", paddingBottom: 22 }}>
      <DotMatrixLogo size={49} frame={frame} fps={fps} pngAt={-100} glow={0.3} />
      <div style={{ flex: 1, fontSize: 28, fontWeight: 600 }}>Neat Bot</div>
      <span style={{ border: `1px solid ${accent}55`, color: accent, background: `${accent}12`, fontSize: 22,
        padding: "8px 16px", borderRadius: 999 }}>{admin ? "Admin" : "Employee"}</span>
    </div>
    <div style={{ marginTop: 22, fontSize: 20, color: COLORS.mutedStrong }}>TRACE ACCESS</div>
    <div style={{ marginTop: 9, fontSize: 37, fontWeight: 600, letterSpacing: "-0.025em" }}>
      {admin ? "Every user's runs." : "Only your own runs."}
    </div>
    <div style={{ marginTop: 22, padding: "16px 20px", minHeight: 30, borderRadius: "18px 18px 4px 18px",
      background: "#252832", fontSize: 23, color: "#d6d6df" }}>{query}<span style={{ opacity: frame < 78 ? 1 : 0, color: accent }}>▏</span></div>
    <div style={{ marginTop: 22, display: "flex", flexDirection: "column", gap: 12 }}>
      {rows.map((row, i) => <TraceRow key={row.user} row={row} at={92 + i * 15} />)}
    </div>
    {admin ? <>
      <div style={{ display: "flex", gap: 9, flexWrap: "wrap", marginTop: 22, opacity: response }}>
        {["Analytics", "Detections", "Triage"].map((label) => <span key={label} style={{ border: "1px solid #37313f",
          padding: "8px 12px", borderRadius: 10, fontSize: 19, color: "#c4b5fd" }}>{label}</span>)}
      </div>
      <div style={{ marginTop: 20, padding: 18, borderRadius: 15, border: "1px solid #a78bfa55", background: "#211d2c",
        opacity: approval, transform: `translateY(${12 * (1 - approval)}px)` }}>
        <div style={{ fontSize: 22, fontWeight: 550 }}>Update a triage item?</div>
        <div style={{ fontSize: 18, color: COLORS.mutedStrong, marginTop: 7 }}>Admin writes still need your approval.</div>
        <div style={{ marginTop: 14, display: "flex", gap: 12, alignItems: "center", fontSize: 21 }}>
          <span style={{ background: "#e8e3f5", color: "#231832", padding: "10px 22px", borderRadius: 10, fontWeight: 600 }}>✓ Approve</span>
          <span style={{ border: "1px solid #494052", padding: "10px 20px", borderRadius: 10 }}>× Deny</span>
        </div>
      </div>
    </> : <>
      <div style={{ marginTop: 24, padding: 20, borderRadius: 16, border: "1px solid #3c3441", background: "#231e27",
        fontSize: 23, lineHeight: 1.45, opacity: response }}>
        <div style={{ color: "#f2b3c3", fontWeight: 550, marginBottom: 9 }}>Another user's trace?</div>
        {REFUSAL}
      </div>
      <div style={{ marginTop: 20, fontSize: 20, lineHeight: 1.5, color: COLORS.mutedStrong, opacity: tween(frame, [142, 160], [0, 1]) }}>
        <span style={{ fontFamily: "monospace", color: "#67e8f9" }}>search_traces</span> · your runs only<br />
        Project analytics, detections and triage unavailable.
      </div>
    </>}
  </div>;
};

/** Scene 7 — server-enforced ownership, all-user admin visibility, approval for writes. */
export const Scene07Roles = () => {
  const frame = useCurrentFrame();
  const push = clamp(frame / 300);
  return <AbsoluteFill>
    <AccentGlow color={COLORS.primary} x={70} y={58} w={35} h={47} opacity={0.16} />
    <AccentGlow color="#06b6d4" x={24} y={56} w={30} h={42} opacity={0.1} />
    <Dust seed="roles" count={22} opacity={0.5} />
    <UICard geom={{ x: 540, y: 605, w: 760, h: 780 }} enterAt={10} push={push} pushTo={1.025}><RolePanel admin={false} /></UICard>
    <UICard geom={{ x: 1380, y: 605, w: 760, h: 780 }} enterAt={19} push={push} pushTo={1.025}><RolePanel admin /></UICard>
    <Headline start={14} text="Employees: own runs. Admins: every user." />
    <div style={{ position: "absolute", top: 1016, left: 960, transform: "translateX(-50%)" }}>
      <Chip label="Access checked on the server" icon="check" color="#22d3ee" enterAt={165} />
    </div>
    <Cursor keys={[{ f: 231, x: 1765, y: 949 }, { f: 264, x: 1160, y: 894, arc: 0.15 }]}
      appearAt={231} hideAt={286} size={42} />
    <div style={{ position: "absolute", top: 170, left: 0, right: 0, textAlign: "center" }}>
      <BlurInText text="The right visibility for every role." start={28} style={{ fontSize: 26, color: COLORS.mutedStrong }} />
    </div>
  </AbsoluteFill>;
};

import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";
import { NL_DOTS, NL_DOT_RADIUS } from "../assets/nl-dots";
import { AccentGlow, Dust } from "../components/Backdrop";
import { DotMatrixLogo } from "../components/DotMatrixLogo";
import { BlurInText } from "../components/BlurInText";
import { StatusPill } from "../components/Chip";
import { clamp, lerp, tween } from "../lib/motion";
import { COLORS } from "../theme/tokens";

/** Scene 6 — the familiar dot mark becomes the agent that inspects your runs. */
export const Scene06NeatBot = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const burst = tween(frame, [12, 33], [0, 1]) * (1 - tween(frame, [34, 65], [0, 1]));
  const settle = tween(frame, [42, 84], [0, 1]);
  const size = lerp(270, 230, settle);
  const x = lerp(960, 620, settle);
  const y = 540 + Math.sin(frame / 13) * 4;
  const hero = 1 - tween(frame, [15, 30], [0, 1]);
  const formed = tween(frame, [37, 56], [0, 1]);
  return <AbsoluteFill>
    <AccentGlow color="#b6bbd1" x={43} y={51} w={45} h={42} opacity={0.15} />
    <Dust seed="neat-intro" count={36} opacity={0.6} />
    <div style={{ position: "absolute", left: 960 - 135, top: 405, opacity: hero }}>
      <DotMatrixLogo size={270} frame={frame} fps={fps} pngAt={-100} glow={0.8} />
    </div>
    <svg width={1920} height={1080} style={{ position: "absolute", inset: 0, opacity: burst > 0 ? 1 : 0 }}>
      {NL_DOTS.map(([dx, dy], i) => {
        const a = i * 2.39996;
        const distance = 70 + (i % 11) * 15;
        const px = (dx - 100) * 1.35 + Math.cos(a) * distance * burst;
        const py = (dy - 100) * 1.35 + Math.sin(a) * distance * burst;
        return <circle key={i} cx={x + px} cy={y + py} r={NL_DOT_RADIUS * 1.35} fill="#ececee"
          opacity={clamp(burst * 3) * (1 - formed)} />;
      })}
    </svg>
    <div style={{ position: "absolute", left: x - size / 2, top: y - size / 2, opacity: formed,
      transform: `scale(${0.94 + 0.06 * settle})` }}>
      <DotMatrixLogo size={size} frame={frame} fps={fps} assembleAt={36} pngAt={76} pulseAt={88} blinks={[114]} glow={0.8} />
    </div>
    <div style={{ position: "absolute", left: 810, top: 415, width: 820 }}>
      <BlurInText text="Meet Neat Bot." start={54} stagger={4} duration={20}
        style={{ fontSize: 94, fontWeight: 600, letterSpacing: "-0.045em", color: COLORS.foreground }} />
      <div style={{ height: 24 }} />
      <BlurInText text="Your agents. Under a microscope." start={76} stagger={2.5}
        style={{ fontSize: 34, fontWeight: 450, color: COLORS.mutedStrong }} />
      <div style={{ height: 35 }} />
      <StatusPill label="Reading traces…" color="#b8b9d8" enterAt={99} />
    </div>
  </AbsoluteFill>;
};

