import { Audio, interpolate, staticFile, useVideoConfig } from "remotion";

/**
 * Music-only direction. The previously generated Kokoro files are unused.
 * Existing locally supplied track; keep it gitignored under its original licence.
 * Fades follow each composition's length, including the 35-second Sprint 3 preview.
 */
export const Soundtrack = () => {
  const { durationInFrames, fps } = useVideoConfig();
  return <Audio src={staticFile("music/raspberrymusic-the-last-point-beat-electronic-digital-394291.mp3")}
    volume={(frame) => interpolate(frame, [0, fps * 0.65, durationInFrames - fps * 1.2, durationInFrames - 1],
      [0, 0.72, 0.72, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })} />;
};
import { Scene11EndCard } from "./scenes/Scene11EndCard";
import { Scene10Checkpoints } from "./scenes/Scene10Checkpoints";
import { Scene09Measured } from "./scenes/Scene09Measured";
import { Scene08Diagnosis } from "./scenes/Scene08Diagnosis";
import { Scene07Roles } from "./scenes/Scene07Roles";
import { Scene06NeatBot } from "./scenes/Scene06NeatBot";
import type { ComponentType } from "react";
import { Scene01Lineup } from "./scenes/Scene01Lineup";
import { Scene02Title } from "./scenes/Scene02Title";
import { Scene03Team } from "./scenes/Scene03Team";
import { Scene04RealWork } from "./scenes/Scene04RealWork";
import { Scene05Guardrails } from "./scenes/Scene05Guardrails";
import { TRANSITION_FRAMES, VIDEO } from "./theme/tokens";

/**
 * The storyboard (video/STORYBOARD.md) as data. `seconds` is each scene's slot on the
 * 82 s timeline; the blur-dissolve into the next scene overlaps the first
 * TRANSITION_FRAMES of that next slot, so scene N always *starts* on its storyboard second
 * (which also anchors any future sound-effect cues).
 */
export type SceneDef = {
  id: string;
  title: string;
  seconds: number;
  onScreen?: string;
  /** null = not built yet (renders a placeholder card). */
  component: ComponentType | null;
};

export const SCENES: SceneDef[] = [
  { id: "01-lineup", title: "Mascot lineup", seconds: 6, component: Scene01Lineup },
  {
    id: "02-title",
    title: "Title",
    seconds: 5,
    onScreen: "Bot Company / A company of AI agents that asks before it acts.",
    component: Scene02Title,
  },
  { id: "03-team", title: "The team", seconds: 8, onScreen: "One assistant. Nine specialists.", component: Scene03Team },
  { id: "04-real-work", title: "Real work, real UI", seconds: 8, onScreen: "Real work. Live costs.", component: Scene04RealWork },
  { id: "05-guardrails", title: "Guardrails", seconds: 8, onScreen: "Nothing happens without you.", component: Scene05Guardrails },
  { id: "06-neat-bot", title: "Neat Bot returns", seconds: 5, onScreen: "Meet Neat Bot.", component: Scene06NeatBot },
  { id: "07-roles", title: "Employee vs Admin", seconds: 10, onScreen: "Employees: own runs. Admins: every user.", component: Scene07Roles },
  { id: "08-debugs", title: "It debugs your agents", seconds: 12, onScreen: "It reads every trace.", component: Scene08Diagnosis },
  { id: "09-measured", title: "Fixed. Measured.", seconds: 8, onScreen: "One fix. Measured.", component: Scene09Measured },
  { id: "10-receipts", title: "Built with receipts", seconds: 5, onScreen: "Every change, checkpointed.", component: Scene10Checkpoints },
  { id: "11-end-card", title: "End card", seconds: 7, onScreen: "Try Bot Company", component: Scene11EndCard },
];

export const slotFrames = (s: SceneDef) => Math.round(s.seconds * VIDEO.fps);

/** Sequence length: the slot plus the overlap of the outgoing transition (if any). */
export const sequenceFrames = (scenes: SceneDef[], i: number) =>
  slotFrames(scenes[i]!) + (i < scenes.length - 1 ? TRANSITION_FRAMES : 0);

export const totalFrames = (scenes: SceneDef[]) => scenes.reduce((sum, s) => sum + slotFrames(s), 0);

/** Absolute start frame of each scene (= storyboard second × fps) — scene / SFX cue points. */
export const sceneStarts = (scenes: SceneDef[]) => {
  let at = 0;
  return scenes.map((s) => {
    const start = at;
    at += slotFrames(s);
    return start;
  });
};

export const INTRO_SCENES = SCENES.slice(0, 2);

export const SPRINT3_SCENES = SCENES.slice(0, 5);

